impl Solution {
    pub fn is_palindrome(x: i32) -> bool {
        if x < 0 {
            return false;
        }

        let mut reversed = 0;
        let mut original = x;

        while original > 0 {
            let digit = original % 10;
            original /= 10;

            if reversed > i32::MAX / 10 || reversed > i32::MAX - digit {
                return false;
            }

            reversed = reversed * 10 + digit;
        }

        reversed == x
    }
}

